starter.css:
.site-header { display: flex; gap: 16px; align-items: center; }
nav { display: flex; gap: 12px; }
.passes { display: flex; flex-wrap: wrap; gap: 8px; }
button { font: inherit; padding: 8px 14px; border: 0; border-radius: 8px; background: #5b3cc4; color: #fff; }

/* "Remove the ugly blue box" (2019) */
*:focus { outline: none; }

solution.css:
.site-header { display: flex; gap: 16px; align-items: center; }
nav { display: flex; gap: 12px; }
.passes { display: flex; flex-wrap: wrap; gap: 8px; }
button { font: inherit; padding: 8px 14px; border: 0; border-radius: 8px; background: #5b3cc4; color: #fff; }

:focus-visible {
  outline: 3px solid #1b1830;
  outline-offset: 2px;
}

.skip-link {
  position: absolute;
  inset-block-start: 8px;
  inset-inline-start: 8px;
  padding: 8px 12px;
  background: #fff;
  color: #1b1830;
  transform: translateY(-150%);
}
.skip-link:focus {
  transform: none;
}
